  for (let cx = x - 1; cx <= x + 2; cx++) for (let cz = z - 1; cz <= z + 2; cz++) {
    const inStack = cx >= x && cx <= x + 1 && cz >= z && cz <= z + 1;
    if (!inStack) w.set(cx, yTop + 1, cz, ...B.slab("cobblestone", "bottom"));
  }
  return w.cells;
}

